for(const a of snapshot.articles){
  const indexes=snapshot.indexes.filter(i=>i.links.includes(a.url)).map(i=>i.title);
  sourcePlatforms[a.id]=/video/i.test(a.url)||a.categories.includes('Video')?['Video']:
    /ipad/i.test(a.url+a.title)?['iPad']:
    /instant/i.test(a.url+a.title)||a.categories.some(x=>/Instant/.test(x))?['Instant']:
    /mobile/i.test(a.url+a.title)||indexes.includes('Evoto Mobile')?['iPhone/Mobile']:
    indexes.includes('Evoto PC')?['Desktop Windows','Desktop macOS']:[];
}
